SELECT * FROM blade_ai_prompt
WHERE tenant_id = #{tenantId} AND is_deleted = 0

    AND prompt_name LIKE CONCAT('%', #{name}, '%')


    AND prompt_code LIKE CONCAT('%', #{code}, '%')


    AND status = #{status}


    AND prompt_type = #{promptType}


    AND publish_mode = #{publishMode}


    AND create_user = #{ownerUserId}

ORDER BY update_time DESC, id DESC

SELECT * FROM blade_ai_prompt
WHERE tenant_id = #{tenantId} AND id = #{id} AND is_deleted = 0

    AND create_user = #{ownerUserId}

SELECT * FROM blade_ai_prompt
WHERE tenant_id = #{tenantId} AND prompt_code = #{code}
LIMIT 1

mapper.update:
UPDATE blade_ai_prompt
SET status = 2, lock_version = lock_version + 1,
    update_user = #{updateUser}, update_time = NOW()
WHERE tenant_id = #{tenantId} AND id = #{id}
  AND create_user = #{ownerUserId}
  AND lock_version = #{expectedLockVersion} AND is_deleted = 0

UPDATE blade_ai_prompt
SET is_deleted = 1, lock_version = lock_version + 1,
    update_user = #{updateUser}, update_time = NOW()
WHERE tenant_id = #{tenantId} AND id = #{id}
  AND create_user = #{ownerUserId}
  AND lock_version = #{expectedLockVersion} AND is_deleted = 0
